{"implementation": "def solve(case):
    attempts = case.get("attempts", [])
    max_attempts = case["max_attempts"]
    if not attempts:
        return {"decision": "continue", "memory_append": None, "next_attempt": 1}
    last = attempts[-1]
    n = len(attempts)
    if last["success"]:
        return {"decision": "stop", "memory_append": None, "next_attempt": n}
    last_sig = last["failure_signature"]
    repeated = any(a["failure_signature"] == last_sig for a in attempts[:-1])
    budget_exceeded = n >= max_attempts
    memory = {"reflection": last["reflection"], "signature": last["failure_signature"]}
    if repeated or budget_exceeded:
        return {"decision": "stop", "memory_append": memory, "next_attempt": n}
    else:
        return {"decision": "continue", "memory_append": memory, "next_attempt": n + 1
